"""Aplica, en tu repo real, el mecanismo de señal-por-resumen para
la detección de temas (última ronda de esta sesión).

Uso (desde la RAÍZ del repo, con el venv activado):
    python aplicar_resumen_temas.py

Qué hace:
  1. Sobrescribe estos 2 archivos con la versión ya probada:
     - src/detectar_temas.py
     - scripts/calcular_temas.py
  2. Compila ambos (py_compile) para detectar errores de sintaxis
     antes de que corras nada más.

Después de correr esto:
    python scripts/calcular_temas.py
    git add -A
    git commit -m "fix: usar resumen ya generado como señal para detectar temas"
    git push
"""
import base64
import py_compile
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent

DETECTAR_TEMAS_B64 = (
    ""
)
CALCULAR_TEMAS_B64 = (
    ""
)

DESTINO_DETECTAR_TEMAS = "src/detectar_temas.py"
DESTINO_CALCULAR_TEMAS = "scripts/calcular_temas.py"


def escribir(ruta_relativa: str, contenido_b64: str) -> Path | None:
    ruta = REPO_ROOT / ruta_relativa
    if not ruta.parent.exists():
        print(f"AVISO: no existe la carpeta {ruta.parent} -- se omite {ruta_relativa}")
        return None
    contenido = base64.b64decode(contenido_b64)
    ruta.write_bytes(contenido)
    print(f"Escrito: {ruta_relativa}")
    return ruta


def main() -> None:
    rutas_escritas = []
    ruta = escribir(DESTINO_DETECTAR_TEMAS, DETECTAR_TEMAS_B64)
    if ruta:
        rutas_escritas.append(ruta)
    ruta = escribir(DESTINO_CALCULAR_TEMAS, CALCULAR_TEMAS_B64)
    if ruta:
        rutas_escritas.append(ruta)

    print()
    if len(rutas_escritas) < 2:
        print("No se escribieron los 2 archivos -- revisa los avisos arriba")
        print("(¿corriste el script desde la raíz del repo?).")
        return

    print("Compilando los archivos escritos...")
    for ruta in rutas_escritas:
        py_compile.compile(str(ruta), doraise=True)
        print(f"  compila OK: {ruta.relative_to(REPO_ROOT)}")

    print()
    print("Listo. Siguiente paso:")
    print("  python scripts/calcular_temas.py")


if __name__ == "__main__":
    main()
